import { NextRequest, NextResponse } from "next/server";
import { getPrisma } from "@/lib/prisma";
import { screenshotToCodePrompt } from "@/lib/prompts";
import { buildProductionCodingPrompt } from "@/lib/prompt-config";
import Together from "together-ai";
import { resolveModel, SCREENSHOT_MODEL } from "@/lib/constants";
import { createLocalChatTitle } from "@/lib/chat-title";
import {
  flushBraintrust,
  getBraintrustLogger,
  logBraintrustFailure,
  serializeBraintrustError,
} from "@/lib/braintrust";
import type { Span } from "braintrust";
import { createValidatedImageDownloadUrl } from "@/lib/s3-image-storage";

export async function POST(request: NextRequest) {
  const logger = getBraintrustLogger();
  let traceStarted = false;

  try {
    const body = await request.json();
    const { prompt, model, screenshotToken } = body;
    const resolvedModel = resolveModel(model);
    const chatId = createId();

    const createChat = async (rootSpan?: Span) => {
      let fullScreenshotDescription;
      if (screenshotToken) {
        try {
          const describeScreenshot = async (span?: Span) => {
            const startedAt = performance.now();
            const screenshotModel = SCREENSHOT_MODEL;
            const together = new Together();
            const screenshotUrl =
              await createValidatedImageDownloadUrl(screenshotToken);

            const screenshotResponse = await together.chat.completions.create({
              model: screenshotModel,
              reasoning: { enabled: false },
              temperature: 0.4,
              max_tokens: 1000,
              messages: [
                {
                  role: "user",
                  content: [
                    { type: "text", text: screenshotToCodePrompt },
                    {
                      type: "image_url",
                      image_url: {
                        url: screenshotUrl,
                      },
                    },
                  ],
                },
              ],
            });

            const description = screenshotResponse.choices[0].message?.content;
            const usage = screenshotResponse.usage ?? undefined;
            span?.log({
              output: description,
              metadata: {
                model: screenshotModel,
                provider: "together",
              },
              metrics: {
                duration_ms: performance.now() - startedAt,
                prompt_tokens: usage?.prompt_tokens ?? 0,
                completion_tokens: usage?.completion_tokens ?? 0,
                tokens: usage?.total_tokens ?? 0,
              },
            });
            return description;
          };

          fullScreenshotDescription = rootSpan
            ? await rootSpan.traced((span) => describeScreenshot(span), {
                name: "llamacoder.describe-screenshot",
                type: "llm",
                event: {
                  input: {
                    prompt,
                    hasScreenshot: true,
                  },
                  metadata: {
                    chatId,
                    route: "/api/create-chat",
                    provider: "together",
                  },
                },
              })
            : await describeScreenshot();
        } catch (err) {
          rootSpan?.log({
            error: serializeBraintrustError(err),
            metadata: {
              chatId,
              screenshotProcessingFailed: true,
            },
          });
          console.warn(
            "Screenshot processing failed, continuing without it:",
            err,
          );
        }
      }

      let userMessage: string;
      if (fullScreenshotDescription) {
        userMessage =
          prompt +
          "RECREATE THIS APP AS CLOSELY AS POSSIBLE: " +
          fullScreenshotDescription;
      } else {
        userMessage = prompt;
      }

      const prisma = getPrisma();
      const lastMessageId = createId();
      const braintrustParent = await rootSpan?.export();
      await prisma.chat.create({
        data: {
          id: chatId,
          model: resolvedModel,
          // The High-quality toggle was removed (benchmark: worse reliability, no
          // quality gain). All generations use the single minimal-v1 × inline path.
          quality: "low",
          prompt,
          title: createLocalChatTitle(prompt),
          braintrustParent,
          shadcn: true,
          messages: {
            create: [
              {
                id: createId(),
                role: "system",
                content: buildProductionCodingPrompt(),
                position: 0,
              },
              {
                id: lastMessageId,
                role: "user",
                content: userMessage,
                position: 1,
              },
            ],
          },
        },
      });

      rootSpan?.log({
        output: {
          chatId,
          lastMessageId,
        },
        metadata: {
          completed: true,
        },
      });

      return NextResponse.json({
        chatId,
        lastMessageId,
      });
    };

    if (!logger) return await createChat();

    traceStarted = true;
    const response = await logger.traced((span) => createChat(span), {
      name: "llamacoder.create-chat",
      type: "task",
      event: {
        input: {
          prompt,
          requestedModel: model,
          hasScreenshot: Boolean(screenshotToken),
        },
        metadata: {
          chatId,
          resolvedModel,
          route: "/api/create-chat",
        },
      },
    });
    await flushBraintrust();
    return response;
  } catch (error) {
    console.error("Error creating chat:", error);
    if (!traceStarted) {
      await logBraintrustFailure(
        {
          name: "llamacoder.create-chat",
          type: "task",
          event: {
            metadata: {
              route: "/api/create-chat",
              phase: "request-validation",
            },
          },
        },
        error,
      );
    }
    await flushBraintrust();
    return NextResponse.json(
      { error: "Failed to create chat" },
      { status: 500 },
    );
  }
}

function createId(size = 16) {
  const alphabet =
    "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ_abcdefghijklmnopqrstuvwxyz-";
  const bytes = new Uint8Array(size);
  crypto.getRandomValues(bytes);

  return Array.from(bytes, (byte) => alphabet[byte & 63]).join("");
}

import { NextRequest, NextResponse } from "next/server";
import Together from "together-ai";
import { getPrisma } from "@/lib/prisma";
import {
  cleanGeneratedChatTitle,
  createLocalChatTitle,
} from "@/lib/chat-title";
import {
  flushBraintrust,
  getBraintrustLogger,
  logBraintrustFailure,
} from "@/lib/braintrust";
import type { Span } from "braintrust";

const TITLE_MODEL = "Qwen/Qwen3.5-9B";

export async function POST(request: NextRequest) {
  const logger = getBraintrustLogger();

  try {
    const body = await request.json().catch(() => null);
    const chatId = body?.chatId;
    if (typeof chatId !== "string" || !chatId) {
      await logBraintrustFailure(
        {
          name: "llamacoder.generate-chat-title",
          type: "llm",
          event: {
            metadata: {
              route: "/api/generate-chat-title",
              phase: "request-validation",
            },
          },
        },
        new Error("Missing chatId"),
      );
      return NextResponse.json({ error: "Missing chatId" }, { status: 400 });
    }

    const prisma = getPrisma();
    let chat;
    try {
      chat = await prisma.chat.findUnique({
        where: { id: chatId },
        select: {
          id: true,
          prompt: true,
          title: true,
          braintrustParent: true,
        },
      });
    } catch (error) {
      await logBraintrustFailure(
        {
          name: "llamacoder.generate-chat-title",
          type: "llm",
          event: {
            input: { chatId },
            metadata: {
              route: "/api/generate-chat-title",
              phase: "chat-lookup",
            },
          },
        },
        error,
      );
      throw error;
    }

    if (!chat) {
      await logBraintrustFailure(
        {
          name: "llamacoder.generate-chat-title",
          type: "llm",
          event: {
            input: { chatId },
            metadata: {
              route: "/api/generate-chat-title",
              phase: "chat-lookup",
            },
          },
        },
        new Error("Chat not found"),
      );
      return NextResponse.json({ error: "Chat not found" }, { status: 404 });
    }

    const generateTitle = async (span?: Span) => {
      const localTitle = createLocalChatTitle(chat.prompt);
      if (chat.title && chat.title !== localTitle) {
        span?.log({
          output: chat.title,
          metadata: {
            skipped: true,
            reason: "title-already-generated",
          },
        });
        return NextResponse.json({ title: chat.title, skipped: true });
      }

      const startedAt = performance.now();
      const together = new Together();
      const response = await together.chat.completions.create({
        model: TITLE_MODEL,
        temperature: 0.2,
        max_tokens: 24,
        chat_template_kwargs: { enable_thinking: false },
        messages: [
          {
            role: "system",
            content:
              "Create a succinct 3-5 word title for this app-building chat. Return only the title.",
          },
          {
            role: "user",
            content: chat.prompt,
          },
        ],
      });
      const usage = response.usage ?? undefined;

      const generatedTitle = cleanGeneratedChatTitle(
        response.choices[0].message?.content ?? "",
        localTitle,
      );

      await prisma.chat.update({
        where: { id: chat.id },
        data: { title: generatedTitle },
      });

      span?.log({
        output: generatedTitle,
        metadata: {
          model: TITLE_MODEL,
          provider: "together",
        },
        metrics: {
          duration_ms: performance.now() - startedAt,
          prompt_tokens: usage?.prompt_tokens ?? 0,
          completion_tokens: usage?.completion_tokens ?? 0,
          tokens: usage?.total_tokens ?? 0,
        },
      });

      return NextResponse.json({ title: generatedTitle });
    };

    if (!logger) return await generateTitle();

    const response = await logger.traced((span) => generateTitle(span), {
      parent: chat.braintrustParent ?? undefined,
      name: "llamacoder.generate-chat-title",
      type: "llm",
      event: {
        input: {
          prompt: chat.prompt,
        },
        metadata: {
          route: "/api/generate-chat-title",
          chatId: chat.id,
          model: TITLE_MODEL,
          provider: "together",
        },
      },
    });
    await flushBraintrust();
    return response;
  } catch (error) {
    console.error("Error generating chat title:", error);
    await flushBraintrust();
    return NextResponse.json(
      { error: "Failed to generate chat title" },
      { status: 500 },
    );
  }
}

import { z } from "zod";
import Together from "together-ai";
import { resolveModel } from "@/lib/constants";
import {
  GENERATION_DEADLINE_MS,
  superviseCompletionStream,
} from "@/lib/completion-stream-lifecycle";
import {
  flushBraintrustSpan,
  logBraintrustFailure,
  serializeBraintrustError,
  startBraintrustSpan,
} from "@/lib/braintrust";
import { getPrisma } from "@/lib/prisma";

function optimizeMessagesForTokens(
  messages: { role: "system" | "user" | "assistant"; content: string }[],
): { role: "system" | "user" | "assistant"; content: string }[] {
  // Strip code blocks from assistant messages except the last 2 to save tokens
  const assistantIndices: number[] = [];
  for (
    let i = messages.length - 1;
    i >= 0 && assistantIndices.length < 2;
    i--
  ) {
    if (messages[i].role === "assistant") {
      assistantIndices.push(i);
    }
  }
  return messages.map((msg, index) => {
    if (msg.role === "assistant" && !assistantIndices.includes(index)) {
      const stripped = msg.content.replace(/```[\s\S]*?```/g, "").trim();
      return {
        ...msg,
        content: stripped || "[code omitted]",
      };
    }
    return msg;
  });
}

const requestSchema = z.object({
  messageId: z.string().min(1),
  model: z.string().min(1),
});

export async function POST(req: Request) {
  const parsed = requestSchema.safeParse(await req.json().catch(() => null));
  if (!parsed.success) {
    await logBraintrustFailure(
      {
        name: "llamacoder.stream-generation",
        type: "llm",
        event: {
          metadata: {
            route: "/api/get-next-completion-stream-promise",
            phase: "request-validation",
          },
        },
      },
      new Error("Invalid request"),
    );
    return new Response("Invalid request", { status: 400 });
  }
  const { messageId, model } = parsed.data;
  const prisma = getPrisma();

  let message;
  try {
    message = await prisma.message.findUnique({
      where: { id: messageId },
      include: {
        chat: {
          select: {
            braintrustParent: true,
          },
        },
      },
    });
  } catch (error) {
    await logBraintrustFailure(
      {
        name: "llamacoder.stream-generation",
        type: "llm",
        event: {
          input: { messageId },
          metadata: {
            route: "/api/get-next-completion-stream-promise",
            phase: "message-lookup",
          },
        },
      },
      error,
    );
    throw error;
  }

  if (!message) {
    await logBraintrustFailure(
      {
        name: "llamacoder.stream-generation",
        type: "llm",
        event: {
          input: { messageId },
          metadata: {
            route: "/api/get-next-completion-stream-promise",
            phase: "message-lookup",
          },
        },
      },
      new Error("Message not found"),
    );
    return new Response(null, { status: 404 });
  }

  let messages;
  try {
    const messagesRes = await prisma.message.findMany({
      where: { chatId: message.chatId, position: { lte: message.position } },
      orderBy: { position: "asc" },
    });

    messages = z
      .array(
        z.object({
          role: z.enum(["system", "user", "assistant"]),
          content: z.string(),
        }),
      )
      .parse(messagesRes);
  } catch (error) {
    await logBraintrustFailure(
      {
        parent: message.chat.braintrustParent ?? undefined,
        name: "llamacoder.stream-generation",
        type: "llm",
        event: {
          input: { messageId },
          metadata: {
            route: "/api/get-next-completion-stream-promise",
            chatId: message.chatId,
            phase: "message-loading",
          },
        },
      },
      error,
    );
    throw error;
  }

  messages = optimizeMessagesForTokens(messages);

  if (messages.length > 10) {
    messages = [messages[0], messages[1], messages[2], ...messages.slice(-7)];
  }

  const together = new Together();
  const resolvedModel = resolveModel(model);
  const temperature = 0.4;
  // 20000, up from the benchmarked 13000: chat USzt_maT7friospM hit the 13k
  // cap mid-file on a detailed prompt, truncating the last fence — the file
  // was dropped and the preview failed with "Cannot resolve". A cap is not a
  // target, so typical generations are unaffected; only would-be truncations
  // keep streaming. The lifecycle deadline below stops unusually long runs
  // before Vercel's hard timeout and lets the client retain completed files.
  const maxTokens = 20000;
  const inputMessages = messages.map((m) => ({
    role: m.role,
    content: m.content,
  }));
  const startedAt = performance.now();
  let firstTokenMs = 0;
  const promptChars = inputMessages.reduce(
    (sum, item) => sum + item.content.length,
    0,
  );

  const span = startBraintrustSpan({
    parent: message.chat.braintrustParent ?? undefined,
    name: "llamacoder.stream-generation",
    type: "llm",
    event: {
      input: {
        messages: inputMessages,
      },
      metadata: {
        route: "/api/get-next-completion-stream-promise",
        chatId: message.chatId,
        messageId,
        requestedModel: model,
        resolvedModel,
        model: resolvedModel,
        provider: "together",
        messageCount: inputMessages.length,
        promptChars,
        temperature,
        maxTokens,
      },
    },
  });

  let stream: ReturnType<typeof together.chat.completions.stream>;
  try {
    stream = together.chat.completions.stream(
      {
        model: resolvedModel,
        reasoning: { enabled: false },
        messages: inputMessages,
        temperature,
        max_tokens: maxTokens,
      },
      { signal: req.signal },
    );
  } catch (error) {
    span?.log({
      error: serializeBraintrustError(error),
      metrics: {
        first_token_ms: firstTokenMs,
        total_generation_ms: performance.now() - startedAt,
      },
    });
    span?.end();
    await flushBraintrustSpan(span);
    throw error;
  }

  stream.on("content", (delta) => {
    if (!firstTokenMs && delta.length > 0) {
      firstTokenMs = performance.now() - startedAt;
      span?.log({
        metrics: {
          first_token_ms: firstTokenMs,
        },
      });
    }
  });

  let didHitGenerationDeadline = false;
  superviseCompletionStream(stream, {
    timeoutMs: GENERATION_DEADLINE_MS,
    onTimeout: () => {
      didHitGenerationDeadline = true;
    },
  })
    .then(async (finalText) => {
      const usage = await stream.totalUsage().catch(() => undefined);
      const completion = await stream.finalChatCompletion().catch(() => undefined);
      const finishReason = completion?.choices?.[0]?.finish_reason ?? null;
      span?.log({
        output: finalText,
        metadata: {
          completed: finishReason !== "length",
          finish_reason: finishReason,
          truncated: finishReason === "length",
          outputChars: finalText?.length ?? 0,
        },
        metrics: {
          first_token_ms: firstTokenMs,
          total_generation_ms: performance.now() - startedAt,
          prompt_tokens: usage?.prompt_tokens ?? 0,
          completion_tokens: usage?.completion_tokens ?? 0,
          tokens: usage?.total_tokens ?? 0,
        },
      });
      span?.end();
      await flushBraintrustSpan(span);
    })
    .catch(async (error) => {
      span?.log({
        error: serializeBraintrustError(error),
        metadata: {
          generationDeadlineMs: GENERATION_DEADLINE_MS,
          timedOut: didHitGenerationDeadline,
        },
        metrics: {
          first_token_ms: firstTokenMs,
          total_generation_ms: performance.now() - startedAt,
        },
      });
      span?.end();
      await flushBraintrustSpan(span);
    });

  return new Response(stream.toReadableStream());
}

