    "export default function App() { return null; }",
    B,
    `${B}ts`,
    "export const listings = [];",
    B,
  ].join("\n");

  const problem = describePathlessFenceProblem(content);
  assert.ok(problem);
  assert.match(problem!, /\{path=/);
  assert.match(problem!, /every file/i);
});

